package packet;
import core.*;
public final class EthernetFrame{private final String destination;private final String source;private final int etherType;private final byte[] payload;public EthernetFrame(String destination,String source,int etherType,byte[] payload){this.destination=destination;this.source=source;this.etherType=etherType;this.payload=payload==null?new byte[0]:payload;}public static ParseResult<EthernetFrame> parse(byte[] data){Diagnostics d=new Diagnostics();if(data==null||data.length<14)return ParseResult.failure("ethernet.truncated","ethernet frame shorter than header");String dst=mac(data,0);String src=mac(data,6);int type=Endian.u16be(data,12);if(type<0x0600)d.low("ethernet.length","802.3 length field observed");return ParseResult.of(new EthernetFrame(dst,src,type,SafeSlice.copy(data,14,data.length-14)),d);}private static String mac(byte[] b,int o){StringBuilder sb=new StringBuilder();for(int i=0;i<6;i++){if(i>0)sb.append(':');int v=b[o+i]&255;if(v<16)sb.append('0');sb.append(Integer.toHexString(v));}return sb.toString();}public String destination(){return destination;}public String source(){return source;}public int etherType(){return etherType;}public byte[] payload(){return payload;}}
